import jsPDF from "jspdf"
import autoTable from "jspdf-autotable"

// Fully independent of generateInvoicePdf.ts — reuses the same brand
// colors and A4/mm layout conventions for a visually consistent look,
// but is its own file so nothing about the existing invoice PDF is
// touched or depended on. The logo below is the same navbar logo
// (src/assets/logo4.png) embedded directly, same approach already
// used in generateInvoicePdf.ts.

const LOGO_B64 = "data:image/png;base64,"
const RED: [number, number, number] = [220, 0, 0]
const DARK: [number, number, number] = [30, 30, 30]
const GREY_BG: [number, number, number] = [248, 248, 248]

interface ServiceRow {
  date: string
  invoiceId: string
  vehicleNumber: string
  serviceName: string
  quantity: number
  amount: number
  total: number
}

interface CustomerInfo {
  name: string
  phone: string
  email: string
  vehicleNumber: string
}

// Groups the flat service list by invoice (same invoice = same date,
// since every line on one invoice shares that invoice's createdAt), so
// the date/invoice number column only has to show once per invoice
// instead of repeating on every single service row.
const groupByInvoice = (services: ServiceRow[]) => {
  const groups: { key: string; date: string; invoiceId: string; rows: ServiceRow[] }[] = []

  services.forEach((s) => {
    const key = s.invoiceId
    let group = groups.find((g) => g.key === key)
    if (!group) {
      group = { key, date: s.date, invoiceId: s.invoiceId, rows: [] }
      groups.push(group)
    }
    group.rows.push(s)
  })

  return groups
}

export const generateCustomerReportPDF = (
  customer: CustomerInfo,
  services: ServiceRow[],
  totalSpent: number
): Blob => {

  const doc = new jsPDF({ unit: "mm", format: "a4" })
  const PW = 210
  const PH = 297
  const ML = 14
  const MR = 14
  const CW = PW - ML - MR

  // Vehicle number goes per-invoice only when the customer has more than
  // one distinct vehicle; otherwise it's shown once in the details box.
  const uniqueVehicleNumbers = Array.from(new Set(services.map((s) => s.vehicleNumber).filter(Boolean)))
  const showVehiclePerInvoice = uniqueVehicleNumbers.length > 1

  // Top accent bar
  doc.setFillColor(...RED)
  doc.rect(0, 0, PW, 4, "F")

  // Logo (top-left) — preserves its real aspect ratio (823x321) rather
  // than forcing it into a mismatched box, which is what was making
  // the name/address block look cramped before.
  const logoW = 58
  const logoH = logoW * (321 / 823)
  doc.addImage(LOGO_B64, "PNG", ML, 10, logoW, logoH)

  // Company details — well clear of the logo below it, generous gaps
  // between the name and the address block so nothing crowds together.
  const nameY = 10 + logoH + 8
  doc.setFont("helvetica", "bold")
  doc.setFontSize(12.5)
  doc.setTextColor(DARK[0], DARK[1], DARK[2])
  doc.text("TYRETRACK PREMIUM AUTO CARE", ML, nameY)

  doc.setFont("helvetica", "normal")
  doc.setFontSize(8)
  const compLines = [
    "107/2, Pasumai Nagar, Opp. Gokulam Apartment, Andipalayam, Mangalam Road, Tiruppur",
    "Phone : 9443738487 / 7448787979",
    "GSTIN : 33AAWFT5612K1ZP",
  ]
  let cy = nameY + 6
  for (const line of compLines) {
    doc.text(line, ML, cy)
    cy += 4.6
  }

  // Clickable website link, same pattern as the real invoice PDF
  doc.setTextColor(...RED)
  doc.textWithLink("www.tyretrack.in", ML, cy, { url: "https://www.tyretrack.in" })
  cy += 4.6

  // Report title (right)
  doc.setFont("helvetica", "bold")
  doc.setFontSize(16)
  doc.setTextColor(...RED)
  const title = "CUSTOMER SERVICE REPORT"
  const titleW = doc.getTextWidth(title)
  doc.text(title, PW - MR - titleW, 20)

  doc.setFont("helvetica", "normal")
  doc.setFontSize(8.5)
  doc.setTextColor(100, 100, 100)
  const generatedText = `Generated: ${new Date().toLocaleDateString("en-IN", {
    day: "2-digit", month: "short", year: "numeric",
  })}`
  const generatedW = doc.getTextWidth(generatedText)
  doc.text(generatedText, PW - MR - generatedW, 26)

  // Divider — pushed down to clear the now-taller header block
  const dividerY = cy + 6
  doc.setDrawColor(220, 220, 220)
  doc.line(ML, dividerY, PW - MR, dividerY)

  // Customer details box — Name gets its own full-width row (and wraps
  // if it's long, e.g. a company name) so it can never run into the
  // Phone label the way a long name did when they shared a row.
  const colXLeft = ML + 4
  const colXRight = ML + CW / 2 + 2
  const labelW = 14 // width reserved for "Name:" / "Phone:" etc. labels

  doc.setFont("helvetica", "normal")
  doc.setFontSize(9)
  const nameMaxWidth = CW - 8 - labelW
  const nameLines = doc.splitTextToSize(customer.name || "-", nameMaxWidth)
  const nameLineHeight = 4.6

  const headerH = 6
  const padTop = 6
  const nameBlockH = nameLines.length * nameLineHeight
  const otherRowsH = 7 + 7 // Phone/Vehicle row + Email row
  const padBottom = 4
  const boxH = headerH + padTop + nameBlockH + otherRowsH + padBottom

  const boxY = dividerY + 5
  doc.setFillColor(...GREY_BG)
  doc.roundedRect(ML, boxY, CW, boxH, 2, 2, "F")
  doc.setFillColor(...RED)
  doc.rect(ML, boxY, CW, headerH, "F")
  doc.setFont("helvetica", "bold")
  doc.setFontSize(9)
  doc.setTextColor(255, 255, 255)
  doc.text("CUSTOMER DETAILS", ML + 4, boxY + 4.3)

  doc.setTextColor(DARK[0], DARK[1], DARK[2])

  const nameRowY = boxY + headerH + padTop
  doc.setFont("helvetica", "bold")
  doc.text("Name:", colXLeft, nameRowY)
  doc.setFont("helvetica", "normal")
  doc.text(nameLines, colXLeft + labelW, nameRowY)

  const rowY1 = nameRowY + nameBlockH + 3
  const rowY2 = rowY1 + 7

  doc.setFont("helvetica", "bold")
  doc.text("Phone:", colXLeft, rowY1)
  doc.text("Vehicle No:", colXRight, rowY1)
  doc.text("Email:", colXLeft, rowY2)

  doc.setFont("helvetica", "normal")
  doc.text(customer.phone || "-", colXLeft + labelW, rowY1)
  const vehicleBoxText = showVehiclePerInvoice ? "Multiple Vehicles" : (uniqueVehicleNumbers[0] || customer.vehicleNumber || "-")
  doc.text(vehicleBoxText, colXRight + 18, rowY1)
  doc.text(customer.email || "-", colXLeft + labelW, rowY2)

  // Services table — grouped by invoice, so the date/invoice number
  // cell spans every service row that belongs to that same invoice
  // instead of repeating on each one.
  const groups = groupByInvoice(services)
  const tableBody: any[] = []

  groups.forEach((group) => {
    const dateStr = new Date(group.date).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" })
    const groupVehicle = group.rows[0]?.vehicleNumber || ""
    const dateLabel = showVehiclePerInvoice && groupVehicle
      ? `${dateStr}\n${group.invoiceId}\n${groupVehicle}`
      : `${dateStr}\n${group.invoiceId}`

    group.rows.forEach((s, idx) => {
      const row: any[] = []

      if (idx === 0) {
        row.push({ content: dateLabel, rowSpan: group.rows.length, styles: { valign: "middle" } })
      }

      row.push(
        s.serviceName,
        String(s.quantity),
        `Rs. ${Number(s.amount).toLocaleString("en-IN", { maximumFractionDigits: 2 })}`,
        `Rs. ${Number(s.total).toLocaleString("en-IN", { maximumFractionDigits: 2 })}`
      )

      tableBody.push(row)
    })
  })

  autoTable(doc, {
    startY: boxY + boxH + 8,
    margin: { left: ML, right: MR },
    head: [["Date / Invoice No.", "Service", "Qty", "Amount", "Total"]],
    body: tableBody.length > 0 ? tableBody : [["-", "No service history found", "-", "-", "-"]],
    theme: "grid",
    styles: {
      font: "helvetica",
      fontSize: 8.5,
      cellPadding: 3,
      textColor: DARK,
      lineColor: [220, 220, 220],
      lineWidth: 0.2,
    },
    headStyles: {
      fillColor: RED,
      textColor: [255, 255, 255],
      fontStyle: "bold",
      halign: "left",
    },
    columnStyles: {
      0: { cellWidth: 42 },
      1: { cellWidth: "auto" },
      2: { cellWidth: 16, halign: "center" },
      3: { cellWidth: 30, halign: "right" },
      4: { cellWidth: 30, halign: "right" },
    },
    alternateRowStyles: { fillColor: GREY_BG },
  })

  // Grand total box, right-aligned below the table
  // @ts-ignore — jspdf-autotable attaches this at runtime
  const afterTableY = (doc as any).lastAutoTable.finalY + 10

  const totalBoxW = 80
  const totalBoxH = 14
  const totalBoxX = PW - MR - totalBoxW

  // Light panel instead of a solid black fill, with the same red accent
  // strip style used on the Customer Details box above, and normal
  // (dark) text for the label rather than white-on-black.
  doc.setFillColor(...GREY_BG)
  doc.roundedRect(totalBoxX, afterTableY, totalBoxW, totalBoxH, 2, 2, "F")
  doc.setFillColor(...RED)
  doc.rect(totalBoxX, afterTableY, 3, totalBoxH, "F")

  doc.setFont("helvetica", "bold")
  doc.setFontSize(10)
  doc.setTextColor(DARK[0], DARK[1], DARK[2])
  doc.text("Total Amount Spent", totalBoxX + 7, afterTableY + 9)

  doc.setFont("helvetica", "bold")
  doc.setFontSize(11)
  doc.setTextColor(...RED)
  const totalText = `Rs. ${Number(totalSpent).toLocaleString("en-IN", { maximumFractionDigits: 2 })}`
  const totalTextW = doc.getTextWidth(totalText)
  doc.text(totalText, totalBoxX + totalBoxW - 5 - totalTextW, afterTableY + 9)

  // Footer
  const footerY = afterTableY + totalBoxH + 14
  doc.setFont("helvetica", "italic")
  doc.setFontSize(7.5)
  doc.setTextColor(140, 140, 140)
  const footerText = "This is a computer-generated customer service report."
  const footerW = doc.getTextWidth(footerText)
  doc.text(footerText, (PW - footerW) / 2, footerY)

  // Bottom accent bar — mirrors the red bar at the very top of the page
  doc.setFillColor(...RED)
  doc.rect(0, PH - 4, PW, 4, "F")

  return doc.output("blob")
}

export const downloadCustomerReportPDF = (
  customer: CustomerInfo,
  services: ServiceRow[],
  totalSpent: number
) => {

  const blob = generateCustomerReportPDF(customer, services, totalSpent)
  const url = URL.createObjectURL(blob)

  // File name is the customer's own name, sanitized for filesystem safety.
  const safeName = (customer.name || "Customer")
    .trim()
    .replace(/[/\\:*?"<>|]/g, "")
    .replace(/\s+/g, " ") || "Customer"

  const link = document.createElement("a")
  link.href = url
  link.download = `${safeName}.pdf`
  document.body.appendChild(link)
  link.click()
  document.body.removeChild(link)
  URL.revokeObjectURL(url)
}
